 void thumbnail(ZipArchiveEntry e,ImageView iv,int id){pool.execute(()->{Bitmap b=null;try{if(video(e)){if(e.getMethod()==ZipArchiveEntry.STORED){MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(direct(e));b=r.getFrameAtTime(1000000);}finally{r.release();}}}else b=decode(e,240);}catch(Exception ignored){}if(b!=null){synchronized(cache){cache.put(e.getName(),b);}Bitmap result=b;ui.post(()->{if(id==gen&&e.getName().equals(iv.getTag()))iv.setImageBitmap(result);});}});}
 void photo(ZipArchiveEntry first){ArrayList<ZipArchiveEntry> photos=new ArrayList<>();for(ZipArchiveEntry e:shown)if(!video(e))photos.add(e);int start=photos.indexOf(first);if(start<0)return;Dialog dialog=new Dialog(this,android.R.style.Theme_Black_NoTitleBar_Fullscreen);FrameLayout layout=new FrameLayout(this);layout.setBackgroundColor(0xff05070b);ZoomView view=new ZoomView(this);layout.addView(view,new FrameLayout.LayoutParams(-1,-1));TextView info=text("",13);info.setPadding(dp(16),dp(16),dp(16),dp(16));info.setBackgroundColor(0x99000000);layout.addView(info,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));TextView x=text("✕",25);x.setPadding(dp(18),dp(18),dp(18),dp(18));layout.addView(x,new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT));x.setOnClickListener(v->dialog.dismiss());int[] index={start},serial={0};Runnable[] show={null};show[0]=()->{ZipArchiveEntry e=photos.get(index[0]);info.setText((index[0]+1)+" / "+photos.size()+"   "+e.getName());view.setImageDrawable(null);view.reset();int request=++serial[0];pool.execute(()->{try{Bitmap b=decode(e,2600);ui.post(()->{if(dialog.isShowing()&&request==serial[0])view.setImageBitmap(b);});}catch(Exception ignored){}});};view.swipe=d->{int n=index[0]+d;if(n>=0&&n<photos.size()){index[0]=n;show[0].run();}};dialog.setContentView(layout);dialog.show();show[0].run();}
 interface Swipe{void move(int d);}class ZoomView extends ImageView{ScaleGestureDetector scale;GestureDetector gesture;float factor=1;Swipe swipe;ZoomView(Context c){super(c);setScaleType(ScaleType.MATRIX);scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){factor=Math.max(1,Math.min(5,factor*d.getScaleFactor()));setScaleX(factor);setScaleY(factor);return true;}});gesture=new GestureDetector(c,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onFling(MotionEvent a,MotionEvent b,float vx,float vy){if(factor<1.2&&Math.abs(b.getX()-a.getX())>80&&Math.abs(vx)>250&&swipe!=null){swipe.move(b.getX()<a.getX()?1:-1);return true;}return false;}public boolean onDoubleTap(MotionEvent e){factor=factor>1?1:2.5f;setScaleX(factor);setScaleY(factor);return true;}});}void reset(){factor=1;setScaleX(1);setScaleY(1);}public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);gesture.onTouchEvent(e);return true;}}
 void play(ZipArchiveEntry e){Dialog dialog=new Dialog(this,android.R.style.Theme_Black_NoTitleBar_Fullscreen);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff05070b);TextView closeButton=text("✕    "+e.getName(),16);closeButton.setPadding(dp(18),dp(20),dp(12),dp(20));root.addView(closeButton);closeButton.setOnClickListener(v->dialog.dismiss());FrameLayout box=new FrameLayout(this);root.addView(box,new LinearLayout.LayoutParams(-1,0,1));SurfaceView surface=new SurfaceView(this);box.addView(surface,new FrameLayout.LayoutParams(-1,-1));TextView progress=text(e.getMethod()==ZipArchiveEntry.STORED?"영상 여는 중…":"압축 영상 준비 중…",14);progress.setGravity(Gravity.CENTER);box.addView(progress,new FrameLayout.LayoutParams(-1,-1));MediaPlayer player=new MediaPlayer();File[] tmp={null};boolean[] stopped={false};dialog.setOnDismissListener(d->{stopped[0]=true;try{player.stop();}catch(Exception ignored){}player.release();if(tmp[0]!=null)tmp[0].delete();});dialog.setContentView(root);dialog.show();Runnable start=()->{if(stopped[0])return;try{player.setDisplay(surface.getHolder());if(tmp[0]!=null)player.setDataSource(tmp[0].getAbsolutePath());else player.setDataSource(direct(e));player.setOnPreparedListener(mp->{if(stopped[0])return;progress.setVisibility(View.GONE);MediaController controls=new MediaController(this);controls.setMediaPlayer(new MediaController.MediaPlayerControl(){public void start(){mp.start();}public void pause(){mp.pause();}public int getDuration(){return mp.getDuration();}public int getCurrentPosition(){return mp.getCurrentPosition();}public void seekTo(int p){mp.seekTo(p);}public boolean isPlaying(){return mp.isPlaying();}public int getBufferPercentage(){return 100;}public boolean canPause(){return true;}public boolean canSeekBackward(){return true;}public boolean canSeekForward(){return true;}public int getAudioSessionId(){return mp.getAudioSessionId();}});controls.setAnchorView(box);controls.setEnabled(true);mp.start();controls.show(5000);box.setOnClickListener(v->controls.show(5000));});player.setOnErrorListener((mp,w,extra)->{progress.setText("지원되지 않는 영상 형식");return true;});player.prepareAsync();}catch(Exception ex){progress.setText("재생 실패: "+ex.getMessage());}};if(e.getMethod()==ZipArchiveEntry.STORED){surface.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder h){start.run();}public void surfaceChanged(SurfaceHolder h,int a,int b,int c){}public void surfaceDestroyed(SurfaceHolder h){}});}else pool.execute(()->{File f=null;try{String name=e.getName(),ext=name.substring(name.lastIndexOf('.'));f=File.createTempFile("video_",ext,getCacheDir());try(InputStream in=zip.getInputStream(e);OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[262144];int n;while((n=in.read(buf))!=-1){if(stopped[0])break;out.write(buf,0,n);}}if(stopped[0]){f.delete();return;}File ready=f;ui.post(()->{tmp[0]=ready;if(surface.getHolder().getSurface().isValid())start.run();else surface.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder h){start.run();}public void surfaceChanged(SurfaceHolder h,int a,int b,int c){}public void surfaceDestroyed(SurfaceHolder h){}});});}catch(Exception ex){if(f!=null)f.delete();ui.post(()->progress.setText("준비 실패: "+ex.getMessage()));}});}
